  'navigation.jumpRisk':['A severe jump failure can change the destination and extend the jump to 1–6 weeks.','Un échec grave peut changer la destination et prolonger le saut à 1–6 semaines.'],
  'navigation.jumpCaution':['A severe failure may divert the jump and make it last 1–6 weeks.','Un échec grave peut dérouter le saut et le faire durer 1–6 semaines.'],
  'navigation.rawRisk':['Raw fuel penalises the jump roll.','Le carburant brut pénalise le jet de saut.'],
  'navigation.driveRisk':['The damaged jump drive penalises the jump roll.','Le moteur de saut endommagé pénalise le jet de saut.'],
  'navigation.approachRisk':['Class E/X port: a failed approach can damage the ship.','Port E/X : une approche ratée peut endommager le vaisseau.'],
  'navigation.customsRisk':['Restricted goods aboard may trigger customs at this world.','Les marchandises réglementées à bord peuvent déclencher un contrôle douanier ici.'],
  'navigation.details':['Services, cargo and travel risks','Services, cargaison et risques du trajet'],
  'navigation.choose':['Choose a world on the chart or in the list. Selecting it does not depart.','Choisissez un monde sur la carte ou dans la liste. La sélection ne lance pas le départ.'],
