  'navigation.unreachable':['This world is beyond the ship’s one-parsec jump range.','Ce monde est hors de portée du saut d’un parsec du vaisseau.'],
  'navigation.noDrive':['The jump drive must be repaired before departure.','Le moteur de saut doit être réparé avant le départ.'],
  'navigation.needFuel':['At least {tons} t of fuel is required to depart.','Il faut au moins {tons} t de carburant pour partir.'],
  'navigation.quickUnavailable':['A quick stop is only possible on arrival, before port work or trade.','Une escale rapide est possible uniquement à l’arrivée, avant le travail au port ou le commerce.'],
